func UpdatesToPB(rs []server.Update) ([]*Update, error) {
	result := make([]*Update, len(rs))
	for i := range rs {
		var err error
		result[i], err = UpdateToPB(rs[i])
		if err != nil {
			return nil, err
		}
	}
	return result, nil
}

// UpdatesFromPB converts a slice of Update to Update.
func UpdatesFromPB(pbs []*Update) ([]server.Update, error) {
	result := make([]server.Update, len(pbs))
	for i, pb := range pbs {
		var err error
		result[i], err = UpdateFromPB(pb)
		if err != nil {
			return nil, err
		}
	}
	return result, nil
}

// SecurityPolicyToPB converts server.SecurityPolicy to SecurityPolicy.
func SecurityPolicyToPB(v server.SecurityPolicy) (SecurityPolicy, error) {
	switch v {
	case server.SecurityPolicyBasic128Rsa15:
		return SecurityPolicy_SECURITY_POLICY_BASIC_128_RSA_15, nil
	case server.SecurityPolicyBasic256:
		return SecurityPolicy_SECURITY_POLICY_BASIC_256, nil
	case server.SecurityPolicyBasic256Sha256:
		return SecurityPolicy_SECURITY_POLICY_BASIC_256_SHA_256, nil
	case server.SecurityPolicyAes128Sha256RsaOaep:
		return SecurityPolicy_SECURITY_POLICY_AES_128_SHA_256_RSA_OAEP, nil
	case server.SecurityPolicyAes256Sha256RsaPss:
		return SecurityPolicy_SECURITY_POLICY_AES_256_SHA_256_RSA_PSS, nil
	default:
		return 0, errors.Newf("unrecognized server.SecurityPolicy value: %v", v)
	}
}

// SecurityPolicyFromPB converts SecurityPolicy to server.SecurityPolicy.
func SecurityPolicyFromPB(v SecurityPolicy) (server.SecurityPolicy, error) {
	switch v {
	case SecurityPolicy_SECURITY_POLICY_BASIC_128_RSA_15:
		return server.SecurityPolicyBasic128Rsa15, nil
	case SecurityPolicy_SECURITY_POLICY_BASIC_256:
		return server.SecurityPolicyBasic256, nil
	case SecurityPolicy_SECURITY_POLICY_BASIC_256_SHA_256:
		return server.SecurityPolicyBasic256Sha256, nil
	case SecurityPolicy_SECURITY_POLICY_AES_128_SHA_256_RSA_OAEP:
		return server.SecurityPolicyAes128Sha256RsaOaep, nil
	case SecurityPolicy_SECURITY_POLICY_AES_256_SHA_256_RSA_PSS:
		return server.SecurityPolicyAes256Sha256RsaPss, nil
	default:
		return server.SecurityPolicy(""), errors.Newf("unrecognized SecurityPolicy value: %v", v)
	}
}
